package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                         // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsYear int64 = 0                              // PIC 99 len=2 = 0
var WsCount int64 = 0                             // PIC 99 len=2 = 0
var WsBalEd string = ""                           // PIC ZZ,ZZZ,ZZ9.99 len=13

// additional globals for file handling
var inputFile *os.File
var scanner *bufio.Scanner
var CurRec SchedRec

func storePic9_8V99(d decimal.Decimal) decimal.Decimal {
	neg := false
	if d.Sign() < 0 {
		neg = true
		d = d.Neg()
	}
	s := d.StringFixed(2)
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := parts[1]
	if len(intPart) > 8 {
		intPart = intPart[len(intPart)-8:]
	}
	recon := intPart + "." + fracPart
	nd, err := decimal.NewFromString(recon)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	if neg {
		nd = nd.Neg()
	}
	return nd
}

func formatWsBalEd(d decimal.Decimal) string {
	// d is assumed rounded to 2 decimals, non-negative
	s := d.StringFixed(2)
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	parts := strings.Split(s, ".")
	intPart := parts[0]
	fracPart := parts[1]
	if len(fracPart) < 2 {
		fracPart = fracPart + strings.Repeat("0", 2-len(fracPart))
	} else if len(fracPart) > 2 {
		fracPart = fracPart[:2]
	}
	if len(intPart) > 8 {
		intPart = intPart[len(intPart)-8:]
	}
	if len(intPart) < 8 {
		intPart = strings.Repeat("0", 8-len(intPart)) + intPart
	}
	digits := intPart // length 8
	pattern := "ZZ,ZZZ,ZZ9"
	outInt := make([]byte, len(pattern))
	suppressed := true
	digitIdx := 0
	for i := 0; i < len(pattern); i++ {
		ch := pattern[i]
		if ch == 'Z' || ch == '9' {
			dch := digits[digitIdx]
			digitIdx++
			isZero := dch == '0'
			if suppressed && ch == 'Z' && isZero {
				outInt[i] = ' '
			} else {
				suppressed = false
				outInt[i] = dch
			}
		} else if ch == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		}
	}
	return string(outInt) + "." + fracPart
}

func parseSchedRec(line string) SchedRec {
	acct := line[0:4]
	prinStr := line[4:11]
	rateStr := line[11:15]
	yearsStr := line[15:16]

	var prin decimal.Decimal
	cleanPrin := strings.ReplaceAll(prinStr, " ", "")
	if cleanPrin == "" {
		prin = decimal.NewFromInt(0)
	} else {
		if n, err := strconv.ParseInt(cleanPrin, 10, 64); err == nil {
			prin = decimal.New(n, -2)
		} else {
			prin = decimal.NewFromInt(0)
		}
	}

	var rate decimal.Decimal
	cleanRate := strings.ReplaceAll(rateStr, " ", "")
	if cleanRate == "" {
		rate = decimal.NewFromInt(0)
	} else {
		if n, err := strconv.ParseInt(cleanRate, 10, 64); err == nil {
			rate = decimal.New(n, -2)
		} else {
			rate = decimal.NewFromInt(0)
		}
	}

	var years int64
	cleanYears := strings.ReplaceAll(yearsStr, " ", "")
	if cleanYears == "" {
		years = 0
	} else {
		if n, err := strconv.ParseInt(cleanYears, 10, 64); err == nil {
			years = n
		} else {
			years = 0
		}
	}

	return SchedRec{ScAcct: acct, ScPrin: prin, ScRate: rate, ScYears: years}
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 16 {
			line += strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		CurRec = parseSchedRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsBal = CurRec.ScPrin
	WsYear = 1
	for WsYear <= CurRec.ScYears {
		factor := decimal.NewFromInt(1).Add(CurRec.ScRate.Shift(-2))
		product := WsBal.Mul(factor)
		rounded := product.Round(2)
		WsBal = storePic9_8V99(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		wsYearStr := fmt.Sprintf("%02d", WsYear)
		fmt.Printf("%s Y%s %s\n", CurRec.ScAcct, wsYearStr, WsBalEd)
		WsYear++
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", CurRec.ScAcct, WsBalEd)
	WsCount++
	// PIC 99 overflow: keep low 2 digits
	if WsCount >= 100 {
		WsCount = WsCount % 100
	}
	ReadPara()
}

func MainPara() {
	var err error
	inputFile, err = os.Open("input.dat")
	if err != nil {
		WsEofFlag = "Y"
		fmt.Printf("SCHEDULES: %02d\n", WsCount)
		return
	}
	defer inputFile.Close()
	scanner = bufio.NewScanner(inputFile)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	fmt.Printf("SCHEDULES: %02d\n", WsCount)
}

func main() {
	MainPara()
}
